{
  "aggregate_id": "DEF-NRS-484A-025::bicycle",
  "classifications": [
    {
      "class": "ru.bicycle",
      "verdict": "underdetermined",
      "reason": "The contract guarantees human power and a wheeled riding vehicle, but not the required wheel arrangement, diameter or general recognition, so the words do not admit the whole class."
    },
    {
      "class": "ru.bus",
      "verdict": "contradicted",
      "reason": "Motor propulsion is not stated to be exclusive, and any bus admitted under the human-power and wheel conditions also satisfies the quoted ru.bicycle contract."
    },
    {
      "class": "ru.child",
      "verdict": "supported",
      "reason": "The contract describes a pedestrian person rather than a wheeled riding device admitted by the definition."
    },
    {
      "class": "ru.commercial_motor_vehicle",
      "verdict": "supported",
      "reason": "Commercial mass or licensing does not establish admission independently, while every admitted member is a human-powered wheeled riding vehicle satisfying the quoted ru.bicycle contract."
    },
    {
      "class": "ru.electric_bicycle",
      "verdict": "contradicted",
      "reason": "An assisting motor does not negate human propulsion, and every member admitted under the human-power and wheel conditions satisfies the quoted ru.bicycle contract."
    },
    {
      "class": "ru.electric_scooter",
      "verdict": "contradicted",
      "reason": "The posted scooter definitions expressly permit rider-provided propulsion, and any scooter admitted under the bicycle conditions satisfies the quoted ru.bicycle contract."
    },
    {
      "class": "ru.emergency_vehicle",
      "verdict": "supported",
      "reason": "Emergency designation supplies no independent admission, while every admitted member must be a human-powered wheeled riding vehicle satisfying the quoted ru.bicycle contract."
    },
    {
      "class": "ru.fire_apparatus",
      "verdict": "supported",
      "reason": "The fire-fighting contract does not require motor propulsion, and every member admitted by the bicycle definition satisfies the quoted ru.bicycle contract."
    },
    {
      "class": "ru.moped",
      "verdict": "supported",
      "reason": "The words 'except a moped' expressly remove the jurisdictionally classified mopeds described by the contract."
    },
    {
      "class": "ru.motor_vehicle",
      "verdict": "contradicted",
      "reason": "Self-propulsion does not expressly preclude an additional human-powered mode, and every admitted member satisfying the bicycle conditions also satisfies the quoted ru.bicycle contract."
    },
    {
      "class": "ru.motorcycle",
      "verdict": "contradicted",
      "reason": "The motorcycle contract does not prohibit human propulsion in addition to motor propulsion, and every admitted member satisfies the quoted ru.bicycle contract."
    },
    {
      "class": "ru.official_vehicle",
      "verdict": "supported",
      "reason": "Official service and identifying equipment provide no independent admission, while every admitted member satisfies the quoted human-powered wheeled riding-vehicle contract."
    },
    {
      "class": "ru.pedestrian",
      "verdict": "supported",
      "reason": "The contract describes a person in a pedestrian capacity and expressly does not stand for a bicycle rider, whereas the definition admits wheeled riding devices."
    },
    {
      "class": "ru.pedestrian_with_white_cane_or_guide_animal",
      "verdict": "supported",
      "reason": "The additional cane, animal or assistance conditions do not change this contract from a pedestrian person into an admitted wheeled riding device."
    },
    {
      "class": "ru.rail_vehicle",
      "verdict": "contradicted",
      "reason": "The bicycle definition contains no rail exclusion, and any admitted human-powered on-track riding device satisfies the quoted ru.bicycle contract."
    },
    {
      "class": "ru.school_bus",
      "verdict": "contradicted",
      "reason": "School designation and markings do not require exclusively motor propulsion, and every member admitted under the bicycle conditions satisfies the quoted ru.bicycle contract."
    },
    {
      "class": "ru.taxicab",
      "verdict": "supported",
      "reason": "The passenger-for-hire contract does not require a motor, and every admitted member must satisfy the quoted human-powered wheeled riding-vehicle contract."
    },
    {
      "class": "ru.tour_bus_or_limousine",
      "verdict": "contradicted",
      "reason": "The lengthened passenger-vehicle branch is not restricted to motor propulsion, and its admitted human-powered wheeled riding devices satisfy the quoted ru.bicycle contract."
    },
    {
      "class": "ru.trailer_or_combination",
      "verdict": "supported",
      "reason": "Any trailer or combination actually admitted must itself meet the human-power, riding and wheel conditions, which place that admitted device within the quoted ru.bicycle contract."
    },
    {
      "class": "ru.transit_bus",
      "verdict": "contradicted",
      "reason": "Transit service and identifying displays do not require exclusively motor propulsion, and every member admitted under the bicycle conditions satisfies the quoted ru.bicycle contract."
    },
    {
      "class": "ru.truck",
      "verdict": "contradicted",
      "reason": "A goods-carrying body and motor propulsion do not expressly prohibit additional human propulsion, and every admitted member satisfies the quoted ru.bicycle contract."
    }
  ]
}

